private async resumeRun(
  run: RunRecord,
  observedSeq: number,
  actor: Actor = SYSTEM_ACTOR,
  retryUncertainScript?: true,
  childRecovery?: Extract<RunEvent, { type: 'run.resumed' }>['childRecovery'],
): Promise<RunRecord> {
  const runId = run.id;
  if (this.draining && !this.drainRuns.has(runId)) this.assertAdmissionOpen();
  if (this.forcing) this.assertAdmissionOpen();
  if (run.status === 'paused') {
    return this.withRunLock(runId, async () => {
      const current = await this.mustGet(runId);
      const events = await this.ports.events.read(runId);
      if (current.status !== 'paused' || (events.at(-1)?.seq ?? 0) !== observedSeq)
        throw new RecoveryRefusedError(
          'RECOVERY_STALE',
          'The run changed since it was shown. Refresh and review its current recovery choices.',
        );
      // The compare-and-set is the admission point. Keep the run paused until the intent
      // commits, so wakes, timers and child completion cannot observe a half-claimed wait.
      await this.ports.events.append(
        runId,
        [
          {
            type: 'run.resumed',
            actor,
            ...(childRecovery ? { childRecovery } : {}),
            ...(retryUncertainScript ? { retryUncertainScript } : {}),
          },
        ],
        { expectedLastSeq: observedSeq },
      );
      const resumed = await this.completePausedResume(runId);
      if (!resumed)
        throw new RecoveryRefusedError(
          'RECOVERY_STALE',
          'The run changed since it was shown. Refresh and review its current recovery choices.',
        );
      return resumed;
    });
  }
  if (
    run.status === 'failed' &&
    (run.failure?.resumable || (await childSessionRecovered(this.ports, run)))
  ) {
    // Leaving a terminal status: the intent is written first, like every terminal transition.
    // The finalization marker of the failure is cleared so the run's next terminal outcome is
    // finalized again; recovery completes a resume whose `run.resumed` is durable. It waits for
    // any finalizer of the failure still in flight, which would otherwise set the marker again.
    // The failure this command saw: its terminal event. Inside the lock the run must still be
    // in that same resumable failure, or the command lost to another one (a concurrent resume,
    // and possibly a newer outcome) and is rejected before it writes anything.
    const observed = terminalEvent(await this.ports.events.read(runId))?.seq;
    const resumed = await this.withRunLock(runId, async () => {
      const current = await this.mustGet(runId);
      const terminal = terminalEvent(await this.ports.events.read(runId));
      if (
        current.status !== 'failed' ||
        !(current.failure?.resumable || (await childSessionRecovered(this.ports, current))) ||

